from pathlib import Path
import subprocess,re,base64
p=Path(__file__).parent/'delivery'
s=subprocess.check_output(['pandoc','-f','markdown','-t','html5',str(p/'article.md')],text=True)
s=re.sub(r'src="(images/[^"]+)"',lambda m:'src="data:image/png;base64,'+base64.b64encode((p/m[1]).read_bytes()).decode()+'"',s)
css='''*{box-sizing:border-box}body{margin:0;background:#fff;color:#202020;font-family:system-ui,-apple-system,"Noto Sans CJK SC",sans-serif;line-height:1.9}main{max-width:860px;margin:0 auto;padding:48px 24px 80px}h1{font-size:32px;line-height:1.5}h2{font-size:25px;margin-top:52px;border-bottom:1px solid #ddd;padding-bottom:12px}h3{font-size:20px;margin-top:30px}p,li{font-size:17px}a{color:#222;text-underline-offset:4px}img{width:100%;height:auto;display:block;margin:28px 0}figure{margin:20px 0}figcaption{font-size:13px;color:#666}table{width:100%;border-collapse:collapse;font-size:15px}td,th{border:1px solid #ccc;padding:9px;text-align:left;overflow-wrap:anywhere}pre{overflow:auto;padding:18px;background:#f4f4f4}blockquote{border-left:3px solid #555;margin:20px 0;padding-left:20px} @media(max-width:500px){main{padding:24px 16px 60px}h1{font-size:25px}h2{font-size:21px}p,li{font-size:16px}td,th{padding:5px;font-size:12px}}'''
(p/'第09篇_间歇需求_图文阅读版.html').write_text('<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>第09篇｜多数日子没有订单，偶尔一单很大</title><meta name="description" content="用匿名服装与禾味模拟案例，讲解间歇需求与Croston、SBA、TSB。"><style>'+css+'</style></head><body><main>'+s+'</main></body></html>')
